package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ArtLiveExamWesternClassicBank3 {
    private const val T = "බටහිර සම්භාව්‍ය කලාව (මිසර, ග්‍රීක, රෝම, පුනරුද, බැරොක්)"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("පුරාණ මිසරයේ සක්කාරා (Saqqara) හි පිහිටි ලොව පැරණිතම පඩි පිරමීඩය නිර්මාණය කළ වාස්තු ශිල්පියා කවුද?", "ඉම්හොටෙප් (Imhotep)", "තුත්මෝස් (Thutmose)", "මයිරන් (Myron)", "බෘනලෙස්කි (Brunelleschi)", "ජෝසර් පාරාවෝ රජු වෙනුවෙන් ඉදිකළ මෙම පඩි පිරමීඩයේ නිර්මාතෘ ඉම්හොටෙප් ඉතිහාසයේ නම් සඳහන් පළමු ශිල්පියාය."),
        q("රාජවංශික මිසරයේ කිංග්ස් නිම්නයෙන් හමු වූ 'ටුටන්ඛාමන් රජුගේ මරණ වෙස්මුහුණ' නිමවා ඇත්තේ කුමන වටිනා ද්‍රව්‍යවලින්ද?", "ඝන රත්තරන් හා ලැපිස් ලැසුලි මැණික්", "කළුගල් කුට්ටි හා තෙත් හුණු බදාමය", "පිළිස්සූ මැටි හා ලාක්ෂා ඉටි වර්ණක", "රන් ආලේපිත දැව හා පිත්තල තහඩු", "කිලෝග්‍රෑම් 11ක් පමණ බරැති මෙම රන් වෙස්මුහුණ පුරාණ මිසර ලෝහ කර්මාන්තයේ උච්චතම නිදසුනකි."),
        q("මිසරයේ 'අබු සිම්බෙල්' (Abu Simbel) මහා දෙවොලේ ඇතුල්වීම ඉදිරිපස තනි පර්වතයේ නෙළා ඇති දැවැන්ත ප්‍රතිමා හතර කවුරුන්ගේද?", "දෙවන රැම්සෙස් පාරාවෝ රජුගේය", "නෙෆර්ටිටි රැජින හා අක්නාටන් රජුගේය", "ග්‍රීක ඇලෙක්සැන්ඩර් අධිරාජ්‍යයාගේය", "මහා කොන්ස්තන්තීනු රජුගේය", "මීටර් 20ක් පමණ උස මෙම හිඳි ප්‍රතිමා පුරාණ මිසර රාජකීය බලය පෙන්වීමට කඳු බෑවුමක නෙළීය."),
        q("මිසර 'මළවුන්ගේ පොත' (Book of the Dead) නමැති පැපිරස් සිතුවම් ලියවිලිවල බහුලව ඇඳ ඇති සුප්‍රකට දර්ශනය කුමක්ද?", "අනූබිස් දෙවියන් මියගිය අයගේ හදවත කිරා බැලීම", "ග්‍රීක ක්‍රීඩකයන් කවපෙත්ත විසි කිරීම", "මධ්‍යකාලීන නයිට්වරුන්ගේ අශ්ව සටන් පෙළ", "පුනරුද ශිල්පීන්ගේ මුහුදු දර්ශන සිතුවම්", "මරණින් මතු ආත්ම විනිශ්චය දැක්වෙන මෙම සිතුවම්වල මාත් දේවතාවියගේ පිහාටුව හා හදවත සංසන්දනය කරයි."),
        q("පුරාණ මෙසපොතේමියාවේ සුමේරියානු යුගයට අයත් 'ඌර් හි රාජකීය ධජය' (Standard of Ur) සරසා ඇති කලා මාධ්‍යය කුමක්ද?", "ලැපිස් ලැසුලි නිල් ගල් හා බෙලිකටු මොසැයික්", "කැන්වස් රෙදි මත තෙල් සායම් සිතුවම්", "ග්‍රීක රතු මැටි හා කළු ඔප බඳුන්", "තඹ තහඩු මත ඇසිඩ් කැටයම් මුද්‍රණය", "යුද්ධය හා සාමය යන දෙපැත්ත නිරූපණය කරන මෙම දැව පෙට්ටිය පැරණි සුමේරියානු කතා කීමේ කලාව පෙන්වයි."),
        q("සුමේරියානු ශිෂ්ටාචාරයේ 'ටෙල් අස්මාර්' (Tell Asmar) දෙවොලෙන් හමු වූ කුඩා පූජක ප්‍රතිමාවල ඇති කැපී පෙනෙන මුහුණු ලක්ෂණය කුමක්ද?", "අතිශය විශාල විවෘත ඇස් හා බැඳගත් අත්", "වසා ගත් දෙනෙත් හා පැතිකඩ මුහුණ", "රැවුල් රහිත සිනහව හා නැමුණු දණහිස්", "සිංහ හිස් හා පක්ෂි පියාපත් යුගලය", "දෙවියන් ඉදිරියේ සදාකාලිකව අවදියෙන් යාඥා කරන බව හැඟවීමට ඇස් ඉතා විශාලව නෙළා ඇත."),
        q("පුරාණ බැබිලෝනියානු රජු හමුරාබිගේ නීති සංග්‍රහය (Code of Hammurabi) කෙටූ කළු බැසෝල්ට් ස්තම්භය ඉහළින් කැටයම් කර ඇත්තේ කවුද?", "සූර්ය හා යුක්ති දෙවි ශමාෂ් හමුරාබිට නීති දීම", "මිසරයේ රා දෙවියන් පිරමීඩ තැනීම", "ඇතීනා දේවිය පාතනන් දෙවොලට වැඩීම", "ශිව දෙවියන් ගිනි වළල්ල තුළ නැටීම", "අධ්‍යාත්මික නීති බලය පෙන්වීමට දෙවියන් සිංහාසනයේ උස්ව හිඳ රජුට මිනුම් දණ්ඩ පිරිනමන අයුරු නෙළා ඇත."),
        q("ක්‍රීට් දූපතේ 'මිනෝවන්' (Minoan) ශිෂ්ටාචාරයට අයත් නොසොස් මාලිගයේ ඇති සුප්‍රකට තෙත් බදාම සිතුවම කුමක්ද?", "ගොනෙකු මතින් පැන යන තරුණයන්ගේ චිත්‍රය", "මොනාලිසාගේ ස්ෆුමාටෝ ආලේඛ්‍ය සිතුවම", "පොම්පේයි නගරයේ මල් නෙළන යුවතිය", "ඊජිප්තුවේ තාරා දේවියගේ රන් සිතුවම", "චලනය, නිල් පසුබිම හා රිද්මයානුකූල වක්‍ර රේඛා නොසොස් මාලිගා චිත්‍රවල විශේෂත්වයයි."),
        q("ග්‍රීක මූර්ති කලාවේ ආකේයික් යුගයෙන් සම්භාව්‍ය යුගයට මාරු වීමේ පළමු පියවර පෙන්වන ප්‍රතිමාව කුමක්ද?", "ක්‍රිටියෝස් බෝයි (Kritios Boy)", "ලැඔකූන් සහ පුත්‍රයෝ (Laocoon)", "මිලෝ හි වීනස් (Venus de Milo)", "නාමර් පුවරුව (Palette of Narmer)", "මුහුණේ ආකේයික් සිනහව ඉවත් වී එක් පාදයකට බර දෙන මුල්ම කොන්ට්‍රපොස්ටෝ ඉරියව්ව මෙහි දැකිය හැකිය."),
        q("සම්භාව්‍ය ග්‍රීක මූර්ති ශිල්පී 'පොලික්ලයිටස්' (Polyclitus) නිර්මාණය කළ පරිපූර්ණ මිනිස් සමානුපාත ආදර්ශ ප්‍රතිමාව කුමක්ද?", "ඩොරිෆොරොස් (හෙල්ල දරන්නා)", "ඩිස්කොබොලස් (කවපෙත්ත විසිකරන්නා)", "සැමෝත්‍රේස් හි ජයග්‍රාහී දේවතාවිය", "ඇපලෝ සහ ඩැෆ්නි මූර්තිය", "ශරීර අවයව අතර ගණිතමය සමබරතාව දක්වන ඔහුගේ 'කැනන්' (Canon) රීතිය මෙම මූර්තියෙන් පැහැදිලි වේ."),
        q("පසුකාලීන සම්භාව්‍ය ග්‍රීක මූර්ති කලාවට මෘදු 'S-වක්‍ර' (S-Curve) ඉරියව්ව හඳුන්වා දුන් ප්‍රකට ශිල්පියා කවුද?", "ප්‍රැක්සිටිලීස් (Praxiteles)", "මයිරන් (Myron)", "බර්නිනි (Bernini)", "දොනතෙල්ලෝ (Donatello)", "හර්මීස් හා ළදරු දියෝනිසස් ප්‍රතිමාව තුළින් ගලට සිනිඳු මාංශ පේශි ගුණයක් එක් කිරීමට ඔහු සමත් විය."),
        q("ඇතැන්ස් ඇක්‍රොපොලිස් භූමියේ 'එරෙක්තියොන්' (Erechtheion) දෙවොලේ වහලය දරා සිටින කාන්තා රූප හැඩැති කුළුණු හඳුන්වන්නේ කෙසේද?", "කැරියැටිඩ්ස් (Caryatids)", "ටෙලමෝන්ස් (Atlantes)", "කොරින්තියානු කුළුණු (Corinthian)", "ගෝපුර කුළුණු (Gopurams)", "නැමූ දණහිස් සහ සිරුරු ඉරියව්වලින් ස්ථිර බව හා ස්ත්‍රී ලාලිත්‍යය එකවර දක්වන ග්‍රීක මූර්ති කුළුණු වේ."),
        q("පුරාණ ග්‍රීසියේ ඇතැන්ස් 'පාතනන්' දෙවොලේ ප්‍රධාන ඇතීනා ප්‍රතිමාව හා පිටත කැටයම් මාලාව නිර්මාණය කළ ප්‍රධාන කලාකරුවා කවුද?", "ෆීඩියාස් (Phidias)", "ජොටෝ (Giotto)", "මසාචියෝ (Masaccio)", "වෙලාස්කේස් (Velazquez)", "ඇතීනා පාතනොස් ප්‍රතිමාව ඇත්දත් හා රන් තහඩු (Chryselephantine) යොදා ෆීඩියාස් විසින් නිමවන ලදී."),
        q("රෝම අධිරාජ්‍යයේ ඉංජිනේරු කලා කුසලතාව පෙන්වන ප්‍රංශයේ පිහිටි තට්ටු තුනේ ආරුක්කු ජල පාලම කුමක්ද?", "පොන්ට් ඩු ගාර්ඩ් (Pont du Gard)", "පැන්තියන් (Pantheon)", "සැන් වයිතාලේ (San Vitale)", "වර්සයිල්ස් මාලිගය (Versailles)", "කිසිදු බදාමයක් නොමැතිව ගල් ආරුක්කු මගින් නගරයට ජලය ගෙන ගිය මෙම ජල මාර්ගය රෝම ආරුක්කු බලය පෙන්වයි."),
        q("රෝමයේ කොලෝසියම් (Colosseum) රංග පීඨයේ පිටත මහල් තුනෙහි පහළ සිට ඉහළට යොදා ඇති ග්‍රීක කුළුණු පිළිවෙළ කුමක්ද?", "ඩෝරික්, අයනික් සහ කොරින්තියන්", "කොරින්තියන්, ඩෝරික් සහ අයනික්", "අයනික්, ටස්කන් සහ මිශ්‍ර පමණි", "සියලු මහල්වල ඩෝරික් කුළුණු පමණි", "පහළ සරල ශක්තිමත් ඩෝරික් කුළුණුවල සිට ඉහළ සැරසිලි වැඩි කොරින්තියන් දක්වා ක්‍රමයෙන් පෙළ ගැසී ඇත."),
        q("මිසරයේ රෝම පාලන සමයේ මමී පෙට්ටි මත තබන ලද අතිශය යථාර්ථවාදී 'ෆයියුම් ආලේඛ්‍ය' (Fayum Portraits) ඇඳි මාධ්‍යය කුමක්ද?", "එන්කොස්ටික් හෙවත් උණු මී ඉටි තීන්ත", "ජල සායම් හා අඟුරු පැන්සල්", "කැන්වස් මත ඇක්‍රිලික් සායම්", "තඹ තහඩු මත ලෝහ කැටයම්", "වර්ණ කුඩු උණු කළ මී ඉටි සමඟ මුසු කර ලී පුවරු මත ඇඳීම නිසා අදටත් දීප්තිමත්ව පවතී."),
        q("රෝම කලා ඉතිහාසයේ මධ්‍යකාලීන රජවරුන්ට ආදර්ශයක් වූ පූර්ණ ලෝකඩ අශ්වාරෝහක ප්‍රතිමාව කාගේද?", "මාර්කස් ඔරේලියස් අධිරාජ්‍යයාගේය", "ජූලියස් සීසර් සෙනෙවියාගේය", "මහා ඇලෙක්සැන්ඩර් රජුගේය", "තුත්මෝස් මූර්ති ශිල්පියාගේය", "ක්‍රිස්තියානි කොන්ස්තන්තීනු යැයි වරදවා ආරක්ෂා කළ බැවින් අදටත් ඉතිරි වූ පැරණි රෝම ලෝකඩ මූර්තියකි."),
        q("බයිසැන්ටයින් අධිරාජ්‍යයේ තුර්කියේ ඉස්තාන්බුල්හි පිහිටි 'හගියා සොෆියා' (Hagia Sophia) දෙව්මැදුරේ මහා ගෝලය රඳවා ඇත්තේ කුමකින්ද?", "පෙන්ඩෙන්ටිව් හෙවත් වක්‍ර ත්‍රිකෝණ ආධාරකවලින්", "උල් ගොතික් පියාඹන ආධාරක බිත්තිවලින්", "සරල ලී කුළුණු හා හල්මිල්ල පේකඩවලින්", "කොන්ක්‍රීට් බාල්ක හා යකඩ දම්වැල්වලින්", "හතරැස් ශාලාවක් මත රවුම් දැවැන්ත ඩෝමයක් රැඳවීමේ පෙන්ඩෙන්ටිව් තාක්ෂණය මෙහි විශිෂ්ට ලෙස යෙදීය."),
        q("ඉතාලියේ රැවෙන්නා හි 'සැන් වයිතාලේ' (San Vitale) බයිසැන්ටයින් දෙව්මැදුරේ ඇති ජස්ටීනියන් හා තියඩෝරා සිතුවම් කුමන මාධ්‍යයෙන් කළේද?", "වීදුරු හා රන් කැබලි මොසැයික්වලින්", "කැන්වස් මත තෙල් සායම් සිතුවම්වලින්", "තෙත් බදාම මත දියසායම් සිතුවම්වලින්", "කළුගල් මත අර්ධ උන්නත කැටයමින්", "රන් පසුබිමක ආලෝකය පරාවර්තනය කරන ටෙසරේ වීදුරු කැබලි ඇතිරීම බයිසැන්ටයින් කලාවේ ලක්ෂණයකි."),
        q("මුල් මධ්‍යකාලීන අයර්ලන්තයේ 'කෙල්ස් පොත' (Book of Kells) වැනි අලංකෘත අත්පිටපත්වල ඇති ප්‍රධාන සැරසිලි රටාව කුමක්ද?", "සංකීර්ණ ගැට ගැසුණු සත්ව හා පටි රටා", "ත්‍රිමාණ ග්‍රීක මිනිස් මූර්ති ඡායාරූප", "පැතලි රතු පසුබිමේ ජපන් කබුකි රූප", "සියුම් ඒකලක්ෂ්‍ය රේඛීය ගොඩනැගිලි", "පැටලුණු කෙල්ටික් ගැට රටා (Interlace) හා විසිතුරු ආරම්භක අකුරු මෙම පුස්තකාල කලාවේ අග්‍ර ඵලයයි."),
        q("11 වන සියවසේ එංගලන්තය ආක්‍රමණය කළ නෝමන් ජයග්‍රහණය නිරූපණය කරන මීටර් 70ක් දිග 'බේයු ටේපස්ට්‍රි' (Bayeux Tapestry) නිර්මාණය කුමක්ද?", "ලිනන් රෙද්දේ වූල් නූලෙන් කළ ගෙත්තමකි", "වීදුරු කැබලිවලින් තැනූ බිත්ති මොසැයික් එකකි", "මැටි පුවරුවල කොටා පිළිස්සූ කැටයමකි", "බිත්ති බදාමයේ ඇඳි ෆ්‍රෙස්කෝ සිතුවමකි", "කොටස් 58කින් කතා පුවත පෙළගස්වන මෙම රෙදි ගෙත්තම මධ්‍යකාලීන ඓතිහාසික කලාවේ අද්විතීය කෘතියකි."),
        q("ප්‍රංශයේ 'චාට්‍රස්' (Chartres) සහ 'නොත්‍රේ-ඩෑම්' ගොතික් ආසන දෙව්මැදුරුවල බිත්ති සිහින් කර උස් ජනෙල් තැබීමට හැකි වූයේ ඇයි?", "පිටත 'පියාඹන ආධාරක' (Flying Buttresses) නිසා", "ඇතුළත කළුගල් කුළුණු දහසක් සවි කළ නිසා", "වහලය තුනී තහඩු හා දැවයෙන් තැනූ නිසා", "මුළු දෙව්මැදුරම භූගත ගුහාවක හෑරූ නිසා", "පියාඹන ආධාරක සහ රිබ් වෝල්ට් මගින් වහලයේ බර පිටතට යොමු කර වර්ණ වීදුරු ජනෙල්වලට ඉඩ සැලසීය."),
        q("පුනරුද කලාවේ පුරෝගාමියා වූ 'ජොටෝ ඩි බොන්ඩෝනේ' (Giotto) ඉතාලියේ පාදුවා හි ස්ක්‍රොවේග්නි දෙව්මැදුරේ ඇඳි කෘතිවල විප්ලවීය වෙනස කුමක්ද?", "රූපවලට සැබෑ බර හා මානව ශෝකය දීම", "මිසර රීතියට පැතලි රූප පමණක් ඇඳීම", "වස්තූන් හතරැස් කියුබ් ලෙස වෙන් කිරීම", "තෙල් සායම් මිශ්‍ර කර ලෝහ මත ඇඳීම", "බයිසැන්ටයින් පැතලි රන් පසුබිමෙන් මිදී භූ දර්ශන තුළ සැබෑ මිනිස් හැඟීම් ප්‍රකාශ කිරීම ජොටෝ ඇරඹීය."),
        q("ෆ්ලෝරන්ස් නගරයේ සැන්ටා මාරියා ඩෙල් ෆියෝරේ දෙව්මැදුරේ දැවැන්ත අෂ්ටාස්‍රාකාර ගෝලය (Duomo) තැනූ පුනරුද වාස්තු ශිල්පියා කවුද?", "ෆිලිපෝ බෘනලෙස්කි (Brunelleschi)", "ලොරෙන්සෝ ගිබර්ටි (Ghiberti)", "මයිකල්ඇන්ජලෝ (Michelangelo)", "ඩියුරර් (Albrecht Durer)", "ද්විත්ව කවච ගඩොල් තාක්ෂණය හා ගණිතමය රේඛීය දෘෂ්ටිකෝණය සොයා ගත්තේද බෘනලෙස්කි විසිනි."),
        q("ෆ්ලෝරන්ස් බව්තීස්ම මැදුරේ මයිකල්ඇන්ජලෝ විසින් 'පාරාදීසයේ දොරටු' (Gates of Paradise) ලෙස අගය කළ ලෝකඩ දොර නිම කළේ කවුද?", "ලොරෙන්සෝ ගිබර්ටි (Lorenzo Ghiberti)", "දොනතෙල්ලෝ (Donatello)", "බොටිචෙල්ලි (Sandro Botticelli)", "රෆායෙල් (Raphael Sanzio)", "රන් ආලේපිත ලෝකඩ පුවරු දහයක ඉතා සියුම් රේඛීය දෘෂ්ටිකෝණයක් සහිතව බයිබල් කතා මූර්තිමත් කළේය."),
        q("මුල් පුනරුද ශිල්පී 'සැන්ඩ්‍රෝ බොටිචෙල්ලි' (Botticelli) නිර්මාණය කළ ග්‍රීක පුරාවෘත්ත මත පදනම් වූ සුප්‍රකට සිතුවම් දෙක මොනවාද?", "වීනස්ගේ උපත සහ වසන්ත සමය (Primavera)", "මොනාලිසා සහ පර්වතයේ කන්‍යාව", "වෙරළේ තරු කැට සහ සූරියකාන්ත මල්", "ඇතන්ස් පාසල සහ සිස්ටයින් මැඩෝනා", "පුනරුද සමයේ ආගමික තේමාවන්ට අමතරව පුරාණ ග්‍රීක-රෝම මිථ්‍යා කතා කලාවට ගෙන ඒමට බොටිචෙල්ලි පුරෝගාමී විය."),
        q("ෆ්ලෝරන්ස් හි සැන් මාර්කෝ ආරාමයේ කුටිවල සාමකාමී හා භක්තිමත් 'මංගල දූත ගමන' (Annunciation) සිතුවම් කළ භික්ෂු චිත්‍ර ශිල්පියා කවුද?", "ෆ්‍රා ඇන්ජලිකෝ (Fra Angelico)", "කැරවැජියෝ (Caravaggio)", "පීටර් පෝල් රූබන්ස් (Rubens)", "ජැක් ලුවී ඩේවිඩ් (J.L. David)", "පියවි දෘෂ්ටිකෝණ ගොඩනැගිලි තුළ ඉතා මෘදු වර්ණ හා ආධ්‍යාත්මික නිහඬතාවක් ඔහුගේ ෆ්‍රෙස්කෝවල ඇත."),
        q("මුල් පුනරුදයේ 'අන්ද්‍රේයා මැන්ටෙග්නා' (Andrea Mantegna) ඇඳි 'මියගිය ක්‍රිස්තුස් වහන්සේ' සිතුවමේ කැපී පෙනෙන ශිල්පීය උපක්‍රමය කුමක්ද?", "පාදයේ සිට හිසට අධික ලෙස කෙටි කර ඇඳීම", "වර්ණ කිසිවක් නැතිව තනි කළු තීන්ත යෙදීම", "සිරුර කියුබ් කැබලි සියයකට කඩා ඇඳීම", "හිස ඉතා විශාල කර පාද ඉතා කුඩා කිරීම", "නරඹන්නා පාමුල සිට බලන කෝණයෙන් ත්‍රිමාණ ගැඹුර මැවීම (Foreshortening) මෙහි අති දක්ෂව යොදා ඇත."),
        q("මයිකල්ඇන්ජලෝ තම 24 වන වියේදී වතිකානුවේ ශාන්ත පීතර බැසිලිකාව සඳහා තනි කිරිගරුඬ ගලින් නෙළූ සංවේදී මූර්තිය කුමක්ද?", "පියෙතා (Pieta) ප්‍රතිමාව", "හර්මීස් සහ ළදරු දියෝනිසස්", "කූරෝස් හා කෝරේ යුගලය", "මිලෝ හි වීනස් මූර්තිය", "මියගිය ජේසුස් වහන්සේ උකුලේ දරා සිටින මරියතුමියගේ වස්ත්‍ර රැලි හා දුක්බර සංයමය අසමසම වේ."),
        q("රෝමයේ සිස්ටයින් දෙව්මැදුරු සිවිලිමේ මයිකල්ඇන්ජලෝ විසින් ඇඳ ඇති වඩාත්ම ප්‍රසිද්ධ දර්ශනය කුමක්ද?", "ආදම් මැවීම (Creation of Adam)", "අවසන් රාත්‍රී භෝජනය (Last Supper)", "ඇතන්ස් පාසල (School of Athens)", "ගොර්නිකා යුද ඛේදවාචකය (Guernica)", "දෙවියන් වහන්සේගේ හා ආදම්ගේ ඇඟිලි තුඩු ළං වන එම අවස්ථාව පුනරුද මානවවාදයේ සංකේතයකි."),
        q("උච්ච පුනරුද ශිල්පී 'රෆායෙල්' (Raphael) වතිකානු මන්දිරයේ ඇඳි 'ඇතන්ස් පාසල' සිතුවමේ මැද සිටින දාර්ශනිකයන් දෙදෙනා කවුද?", "ප්ලේටෝ සහ ඇරිස්ටෝටල්", "ලියනාඩෝ සහ මයිකල්ඇන්ජලෝ", "සීසර් සහ මාර්කස් ඔරේලියස්", "ගෞතම බුදුන් සහ මිහිඳු හිමි", "අහස දෙසට ඇඟිල්ල දිගු කරන ප්ලේටෝ (අධ්‍යාත්මය) හා පොළොවට අත දිගු කරන ඇරිස්ටෝටල් (විද්‍යාව) මධ්‍යයේ වේ."),
        q("රෆායෙල් සිතුවම් කළ 'ඇතන්ස් පාසල' කෘතිය ඒකලක්ෂ්‍ය දෘෂ්ටිකෝණයේ විශිෂ්ට නිදසුනක් වන්නේ කෙසේද?", "සියලු ආරුක්කු රේඛා මධ්‍ය දාර්ශනිකයන් වෙත එල්ල වීම", "කිසිදු ගොඩනැගිලි පසුබිමක් නොමැතිව ඇඳීම", "වස්තූන් ඉහළ කොනේ සිට පහළට විහිදී යාම", "රූප සියල්ල එකම සිරස් කෙළින් රේඛාවක තැබීම", "පසුබිම් රෝමානු ආරුක්කු තුළින් අභිසාරී ලක්ෂ්‍යය කෙළින්ම ප්ලේටෝ හා ඇරිස්ටෝටල් අතරට ගෙන එයි."),
        q("මැනරිසම් (Mannerism) ශෛලියට අයත් බෙන්වෙනූටෝ චෙලීනි (Cellini) හෝ ජියැම්බොලොග්නාගේ මූර්තිවල පෙනෙන ආකෘතිය කුමක්ද?", "සර්පිලාකාර ඇඹරුණු ත්‍රිමාණ (Serpentinata) හැඩය", "තද සෘජු ඉදිරිපස මිසර සමමිතිය", "සිදුරු සහිත වියුක්ත ලෝහ තහඩු හැඩය", "සරල කළ ජ්‍යාමිතික කියුබ් කැට හැඩය", "සෑම පැත්තකින්ම බලන විට අලංකාර වක්‍ර චලනයක් පෙනෙන සේ මැනරිස්ට් මූර්ති ඇඹීය."),
        q("වැනීසියානු පුනරුද චිත්‍ර කලාව ෆ්ලෝරන්ස් කලාවෙන් වෙනස් වන ප්‍රධාන ලක්ෂණය කුමක්ද?", "රේඛාවට වඩා වර්ණ දීප්තියට හා ආලෝකයට මුල් තැන දීම", "දැඩි ජ්‍යාමිතික රේඛා සිතුවම්වලට පමණක් සීමා වීම", "කැන්වස් වෙනුවට ගල් පුවරු මත පමණක් ඇඳීම", "කළු-සුදු තාන පමණක් භාවිත කර වර්ණ ඉවත් කිරීම", "ජියෝර්ජියෝන්, ටිෂන් සහ ටින්ටොරෙටෝ තෙල් සායම් කැන්වස්වල උණුසුම් වර්ණ හා වායුගෝලය ප්‍රමුඛ කළහ."),
        q("ලියනාඩෝ ඩා වින්චිගේ 'පර්වතයේ කන්‍යාව' (Virgin of the Rocks) සිතුවමේ ප්‍රධාන චරිත සකසා ඇති සංයුති හැඩය කුමක්ද?", "සමබර පිරමීඩ හෙවත් ත්‍රිකෝණාකාර සංයුතිය", "කෙළවරින් කැඩුණු විකර්ණ චලන සංයුතිය", "සමාන්තර තිරස් තීරු හතරක සංයුතිය", "වෘත්තාකාර කේන්ද්‍ර රහිත විසිරුණු සංයුතිය", "උච්ච පුනරුද සිතුවම්වල ස්ථාවරත්වය හා සමබරතාව ගැනීමට ත්‍රිකෝණ සංයුතිය බහුලව යොදා ගැණිනි."),
        q("උතුරු යුරෝපයේ 'මුද්‍රණ ශිල්පය' (Printmaking - Woodcut & Engraving) ස්වාධීන උසස් කලාවක් බවට පත් කළ ජර්මානු ශිල්පියා කවුද?", "ඇල්බ්‍රෙච්ට් ඩියුරර් (Albrecht Durer)", "පීටර් පෝල් රූබන්ස් (Peter Paul Rubens)", "ක්ලෝඩ් මොනේ (Claude Monet)", "ෆිලිපෝ බෘනලෙස්කි (Brunelleschi)", "ඩියුරර්ගේ 'නයිට්, මරණය සහ යක්ෂයා' වැනි තඹ තහඩු කැටයම් මුද්‍රණ ඉතාලි පුනරුදය තරමටම පිළිගැනිණි."),
        q("ජර්මානු පුනරුද ශිල්පී ඇල්බ්‍රෙච්ට් ඩියුරර් ඇඳි ස්වභාව අධ්‍යයන අතර ලෝක ප්‍රසිද්ධ ජල සායම් සිතුවම් දෙක මොනවාද?", "තරුණ හාවා (Young Hare) සහ තණපඳුර (Turf)", "සූරියකාන්ත මල් සහ තාරකා රාත්‍රිය", "ජල මානෙල් පොකුණ සහ කඳු මුදුන", "කැන්ටබරි දෙව්මැදුර සහ සීගිරි උයන", "සොබාදහමේ සියුම් ලොම් හා ශාක පත්‍ර පවා විද්‍යාත්මක නිරීක්ෂණයෙන් ඇඳීමට ඩියුරර් දක්ෂ විය."),
        q("බැරොක් යුගයේ ඉතාලියානු ශිල්පී 'කැරවැජියෝ' (Caravaggio) තම සිතුවම්වල භාවිත කළ තද අඳුර හා ආලෝක ප්‍රතිවිරෝධතාව කුමක්ද?", "ටෙනෙබ්‍රිසම් (Tenebrism / Dramatic Chiaroscuro)", "ස්ෆුමාටෝ මෘදු දුමාර ක්‍රමය (Sfumato)", "පොයින්ටිලිසම් තිත් ක්‍රමය (Pointillism)", "වෙට්-ඔන්-වෙට් ජල සායම් (Wet-on-Wet)", "වේදිකා ආලෝක ධාරාවක් මෙන් කළු පසුබිමෙන් රූප ඉස්මතු කිරීමෙන් ඔහු තීව්‍ර නාට්‍යමය ගුණයක් මැවීය."),
        q("කැරවැජියෝ සිතුවම් කළ 'ශාන්ත මැතිව් කැඳවීම' (Calling of St. Matthew) සිතුවමේ ආලෝක කිරණයෙන් ඉටු කරන කාර්යය කුමක්ද?", "නරඹන්නාගේ ඇස කෙළින්ම මැතිව් වෙත යොමු කිරීම", "සමස්ත කාමරයම දහවල් හිරු එළියෙන් සමව පිරවීම", "බිත්තියේ ඇති සියලුම චරිත අඳුරේ සඟවා තැබීම", "පසුබිමේ ග්‍රීක දෙවොලක් පැහැදිලිව පෙන්වීම", "ජේසුස් වහන්සේගේ අතට ඉහළින් එන විකර්ණ ආලෝක ධාරාව මානව තේරීම හා දේව කැඳවීම නාට්‍යමය කරයි."),
        q("බැරොක් යුගයේ ශ්‍රේෂ්ඨතම මූර්ති ශිල්පී 'බර්නිනි' (Bernini) නෙළූ 'ඩේවිඩ්' ප්‍රතිමාව මයිකල්ඇන්ජලෝගේ ඩේවිඩ්ගෙන් වෙනස් වන්නේ කෙසේද?", "ගල විසි කිරීමට සැරසෙන ක්‍රියාශීලී ඇඹරුණු මොහොතයි", "කිසිදු චලනයක් නැතිව සන්සුන්ව සිටගෙන සිටීමයි", "වයස අවුරුදු අසූවක මහලු මිනිසෙකු ලෙස නෙළීමයි", "තනි ලෝකඩ තහඩුවකින් පැතලිව කැපීමයි", "පුනරුද සන්සුන් බව වෙනුවට තොල් සපාගෙන සිරුර ඇඹරෙන තීව්‍ර ක්‍රියාකාරී මොහොත බැරොක් ලක්ෂණයයි."),
        q("රෝමයේ සැන්ටා මාරියා ඩෙලා විටෝරියා දෙව්මැදුරේ බර්නිනි විසින් නෙළන ලද රංගශාලාමය බැරොක් මූර්තිය කුමක්ද?", "ශාන්ත තෙරේසාගේ ප්‍රහර්ෂය (Ecstasy of St. Teresa)", "සැමෝත්‍රේස් හි ජයග්‍රාහී දේවතාවිය", "ඩොරිෆොරොස් හෙවත් හෙල්ල දරන්නා", "ලොරෙන්සෝ ගිබර්ටිගේ පාරාදීස දොරටුව", "පාවෙන කිරිගරුඬ වලාකුළු හා රන් ආලෝක කිරණ එක්ව බිහි වූ නාට්‍යමය ආධ්‍යාත්මික මූර්තියකි."),
        q("රෝමයේ ශාන්ත පීතර බැසිලිකාව ඉදිරිපස ඇති විවෘත අත් දෙකක් මෙන් නරඹන්නන් පිළිගන්නා කුළුණු චතුරශ්‍රය නිම කළේ කවුද?", "ජියන් ලොරෙන්සෝ බර්නිනි (Bernini)", "ලියනාඩෝ ඩා වින්චි (Leonardo da Vinci)", "රෙම්බ්‍රාන්ට් වැන් රේන් (Rembrandt)", "වින්සන්ට් වැන් ගෝ (Van Gogh)", "අණ්ඩාකාර චතුරශ්‍රය වටා පිහිටි ටස්කන් කුළුණු පෙළ බැසිලිකාවේ විශාලත්වය තවත් උද්දීපනය කරයි."),
        q("ලන්දේසි ස්වර්ණමය යුගයේ චිත්‍ර ශිල්පී 'රෙම්බ්‍රාන්ට්' (Rembrandt) තම ජීවිත කාලය පුරාම ඉතා ගැඹුරින් සිතුවම් කළ විශේෂිත ශානරය කුමක්ද?", "මනෝවිද්‍යාත්මක ස්වයං-ආලේඛ්‍ය (Self-Portraits)", "දැවැන්ත මුහුදු යුද නැව් හා සිතියම්", "ග්‍රීක පුරාවෘත්තවල රංගන දේවතාවියන්", "පැතලි අමූර්ත ජ්‍යාමිතික රටා නිර්මාණ", "තරුණ වියේ සිට මහලු විය දක්වා ඔහු ඇඳි ස්වයං-ආලේඛ්‍ය මිනිස් මනසේ අභ්‍යන්තර අත්දැකීම් කියාපායි."),
        q("රෙම්බ්‍රාන්ට් ඇඳි 'රාත්‍රී මුරසේවය' (The Night Watch) සමූහ ආලේඛ්‍ය සිතුවම කලාවේ විප්ලවයක් වූයේ ඇයි?", "පෙළට සිටගෙන නොසිට චලනය වන නාට්‍යමය සංයුතිය නිසා", "සියලු භටයන් අඳුරේ නොපෙනී ගොස් ඇති නිසා", "වර්ණ කිසිවක් නැතිව සුදු රෙද්දේ පමණක් ඇඳි නිසා", "කඩදාසි කැබලි අලවා කොලාජ් කළ නිසා", "සාම්ප්‍රදායික සමූහ ඡායාරූප රීතිය බිඳ දමමින් ක්‍රියාකාරී ආලෝකය හා ගැඹුර මෙහි එක් කළේය."),
        q("ලන්දේසි චිත්‍ර ශිල්පී 'ජොහැන්නස් වර්මියර්' (Johannes Vermeer) සිතුවම්වල (උදා: මුතු කරාබුවක් පැළඳි යුවතිය) ප්‍රධාන ලක්ෂණය කුමක්ද?", "වම් ජනේලයෙන් එන නිහඬ ස්වභාවික දිවා ආලෝකය", "තීව්‍ර යුද පිටියේ රතු ලේ වැගිරීම්", "අධික වේගවත් කැඩුණු පින්සල් පහරවල්", "ගිනි මැලයක් වටා සිටින අඳුරු භූත රූප", "නිල් (Ultramarine) හා කහ වර්ණ යොදා දෛනික ගෘහස්ථ නිශ්චල මොහොතකට අමුතු ගෞරවයක් ඔහු දුන්නේය."),
        q("ස්පාඤ්ඤ රාජ සභා චිත්‍ර ශිල්පී දියේගෝ වෙලාස්කේස් (Velazquez) ඇඳි 'ලාස් මෙනිනාස්' (Las Meninas) සිතුවමේ සුවිශේෂත්වය කුමක්ද?", "චිත්‍ර ශිල්පියාත් කණ්ණාඩියේ රජ යුවළත් පෙන්වන දෘෂ්ටියයි", "මාර්ගරීටා කුමරිය තනිව වනයේ සිටින භූ දර්ශනයකි", "වියුක්ත කළු ඉරි හා සුදු කොටු රටාවකි", "සම්පූර්ණයෙන්ම ජල සායමින් ඇඳි මුහුදු දර්ශනයකි", "නරඹන්නා, කලාකරුවා හා පසුබිම් කැඩපත අතර ඇති දෘෂ්ටිකෝණ ප්‍රහේලිකාව බටහිර කලාවේ බුද්ධිමත්ම සිතුවමකි."),
        q("ප්‍රංශ බැරොක් කලාවේ දැවැන්තභාවය හා 14 වන ලුවී රජුගේ බලය සංකේතවත් කරන සුප්‍රකට රාජකීය මාලිගය කුමක්ද?", "වර්සයිල්ස් මාලිගය හා කැඩපත් ශාලාව", "ලන්ඩන් බකිංහැම් මාලිගය හා කුළුණ", "ෆ්ලෝරන්ස් මෙඩිචි පවුලේ වෙචියෝ මැදුර", "රෝම කොලෝසියම් හා පැන්තියන් දෙවොල", "සමමිතික උද්‍යාන, ජල උල්පත් හා රන් ආලේපිත කැඩපත් ශාලාව රාජකීය බැරොක් ප්‍රෞඪත්වය පෙන්වයි."),
        q("ෆ්ලෙමිෂ් බැරොක් ශිල්පී 'පීටර් පෝල් රූබන්ස්' (Rubens) තම සිතුවම්වල භාවිත කළ ප්‍රධාන ශෛලීය ගුණාංග මොනවාද?", "පිරිපුන් සිරුරු, විකර්ණ චලනය හා උණුසුම් රතු පැහැය", "තනි කෙළින් රේඛා හා පැතලි සුදුමැලි වර්ණ", "කුඩා අණු වැනි තිත් හා නිහඬ ජ්‍යාමිතික හැඩ", "දැඩි කළු-සුදු කාටූන් සමෝච්ඡ රේඛා", "සිතුවම්වල ජවය, මාංශ පේශි ශක්තිය හා උතුරා යන ජීව ගුණය රූබන්ස් ශෛලියේ ලක්ෂණ වේ.")
    )
}
